package store.cadera.cdrjobs.api;
import org.bukkit.entity.Player;import store.cadera.cdrjobs.data.Database;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.service.ProgressionService;import store.cadera.cdrjobs.util.JobRanks;import java.util.UUID;
public final class CdrJobsAPI {public static final int API_VERSION=1;private final Database database;private final ProgressionService progression;public CdrJobsAPI(Database d,ProgressionService p){database=d;progression=p;}public int getApiVersion(){return API_VERSION;}public JobProgress getProgress(UUID u,JobType j){return database.getProgress(u,j);}public int getLevel(UUID u,JobType j){return getProgress(u,j).level();}public long getXp(UUID u,JobType j){return getProgress(u,j).xp();}public int getFateEssence(UUID u){return database.getFateEssence(u);}public String getRankTitle(UUID u,JobType j){return JobRanks.title(j,getLevel(u,j));}public JobType getHighestProfession(UUID u){JobType best=JobType.MINER;int level=-1;for(JobType j:JobType.values()){int current=getLevel(u,j);if(current>level){level=current;best=j;}}return best;}public JobProgress addXp(Player p,JobType j,long amount){return progression.addXp(p,j,amount);}}
